function splitDomainTokens(hostname) {
  const abbrevMap = {
    sg: 'singapore',
    sgp: 'singapore',
    med: 'medical',
    fmc: 'family medicine clinic',
    gp: 'general practice',
    clin: 'clinic',
    hosp: 'hospital',
    ctr: 'center',
    centre: 'center',
    grp: 'group',
    hldg: 'holdings',
    hldgs: 'holdings',
    paincare: 'paincare',
    onecare: 'onecare',
    doctor: 'doctor',
    doctors: 'doctors',
  };

  const rawTokens = hostname
    .toLowerCase()
    .replace(/^www\./i, '')
    .replace(/\.(com|org|net|gov|edu)(\.sg)?$/i, '')
    .replace(/\.sg$/i, '')
    .split(/[^a-z0-9]+/)
    .filter(Boolean);

  const expanded = new Set();
  for (const token of rawTokens) {
    expanded.add(token);
    if (abbrevMap[token]) {
      for (const part of abbrevMap[token].split(/\s+/).filter(Boolean)) expanded.add(part);
    }
  }
  return [...expanded];
}

