  const domainOverlap = companyTokens.filter((token) => domainTokens.includes(token));
  const titleOverlap = companyTokens.filter((token) => titleTokens.includes(token));
  const exactDomainMatch = companyTokens.length > 0 && companyTokens.every((token) => domainTokens.includes(token));
  const tldBonus = /\.(com\.sg|org\.sg|sg)$/i.test(hostname) ? 2 : 0;
  const compactHost = hostname.replace(/^www\./i, '').replace(/\.(com|org|net|gov|edu)(\.sg)?$/i, '').replace(/\.sg$/i, '').replace(/[^a-z0-9]/g, '');
  const acronymBonus = companyInitials && compactHost.startsWith(companyInitials) ? 12 : 0;
  const firstTokenPrefixBonus = firstSignificantToken.length > 2 && compactHost.startsWith(firstSignificantToken) ? 8 : 0;
  const firstTokenContainsBonus = firstSignificantToken.length > 2 && compactHost.includes(firstSignificantToken) ? 4 : 0;
  const singaporePrefixBonus = companyHasSingaporeToken && firstSignificantToken.length > 2 && compactHost.startsWith('sg' + firstSignificantToken) ? 10 : 0;
  const fmcBonus = compactHost.includes('fmc') && companyTokens.some((token) => ['family', 'medicine', 'clinic'].includes(token)) ? 10 : 0;
  const paincareBonus = compactHost.includes('paincare') && companyTokens.includes('paincare') ? 10 : 0;
  const onecareBonus = compactHost.includes('onecare') && companyTokens.includes('onecare') ? 10 : 0;
  const doctorsBonus = compactHost.includes('doctors') && companyTokens.includes('doctors') ? 6 : 0;
  const holdingsBonus = companyTokens.includes('holdings') && /(holdings|group)/i.test(String(result.title || '') + ' ' + String(result.content || result.snippet || '')) ? 6 : 0;
  const score = (domainOverlap.length * 10) + (titleOverlap.length * 3) + (exactDomainMatch ? 50 : 0) + tldBonus + acronymBonus + firstTokenPrefixBonus + firstTokenContainsBonus + singaporePrefixBonus + fmcBonus + paincareBonus + onecareBonus + doctorsBonus + holdingsBonus + (pathInfo.path === '/' ? 15 : 0) - (idx * 0.5);

  return {
    rank: idx + 1,
    title: String(result.title || '').trim(),
    url: rawUrl,
    homepage,
    hostname,
    snippet: String(result.content || result.snippet || '').trim(),
    score,
    exactDomainMatch,
    domainOverlap: domainOverlap.length,
    titleOverlap: titleOverlap.length,
  };
}).filter(Boolean).sort((a, b) => b.score - a.score || a.rank - b.rank);

const top = candidates[0] || null;
const candidate_summary = candidates.slice(0, 8)
  .map((c, index) => String(index + 1) + '. score=' + c.score.toFixed(1) + ' | ' + c.homepage + ' | ' + c.title)
  .join('\n');

if (!top) {
  return { json: { best_url: 'none', skipllm: true, top_score: 0, search_results_count: results.length, candidate_summary, candidates: candidates.slice(0, 8) } };
}

if (top.score >= 15) {
  return { json: { best_url: top.homepage, skipllm: true, top_score: top.score, search_results_count: results.length, candidate_summary, candidates: candidates.slice(0, 8) } };
}

return { json: { best_url: '', skipllm: false, top_score: top.score, search_results_count: results.length, candidate_summary, candidates: candidates.slice(0, 8) } };

const current = $json || {};
const track = String(current.message_track || '').trim();
const status = track === 'OUT_OF_SCOPE'
  ? 'out of scope'
  : track === 'UNKNOWN'
    ? 'classification review'
    : String(current.status || 'classification review');
return { json: { Id: current.Id || $('Loop Over Items').item.json.Id, status, ...current } };
